/* From Uiverse.io by sandeepgopan - Tags: hover, input, theme-switch, radio, futuristic-radio-buttons */
.__UIV_SCOPE__ .radio-compont {
  display: flex;
  font-family: 'Courier New', Courier, monospace;
  padding: 10px;
  cursor: pointer;
  transition: 0.3s;
}

.__UIV_SCOPE__ .radio-text {
  padding: 0px 10px;
  color: hsl(0, 0%, 50%);
  font-size: 20px;
  text-transform: uppercase;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
}

.__UIV_SCOPE__ .radio-compont:hover {
  box-shadow: inset 4px 4px 12px #afaeae,inset -4px -4px 12px #ffffffc9;
  border-radius: 100px;
}

.__UIV_SCOPE__ .radiostyle:checked~.radio-text {
  color: #E41C23;
}

.__UIV_SCOPE__ .radiostyle {
  width: 20px;
  height: 20px;
}
